    <h1 class="text-left text-xl font-bold mt-7 mb-4" id="skills">专业技能</h1>
    <el-input type="textarea" :rows="6" v-model="skill" />
    <h1 class="text-left text-xl font-bold mt-7 mb-4" id="eduction">教育经历</h1>
    <section class="text-left space-y-4">
      <div class="p-4 border rounded-lg cursor-pointer" v-for="(item , index ) in  data1" :key="index" >
        <div class="flex justify-between"  @click="item.isDown = !item.isDown">
          <h1 class="text-base font-bold">{{item.name}}</h1>
          <div>
            <i :class="`${!item.isDown  ? 'el-icon-arrow-down' : 'el-icon-arrow-up'} `"></i>
          </div>
        </div>
        <p class="mt-1">
          <span>{{item.zhiwei}}</span>
          <span class="px-4">|</span>
          <span>{{item.time}}</span>
        </p>
        <div :class="`${!item.isDown ? 'h-0' : 'h-full pt-5'}  overflow-hidden ` ">
          <a-row :gutter="[30,30]">
            <a-col :span="12">
              <p class="text-left">学校名称</p>
              <a-input class="mt-2" placeholder="请输入学校名称" v-model="education_experience.school"/>
            </a-col>
            <a-col :span="12">
              <p class="text-left">学历</p>
              <a-select placeholder="请选择学历" class="w-full mt-2" v-model="education_experience.degree">
                <a-select-option value="大专">大专</a-select-option>
                <a-select-option value="本科">本科</a-select-option>
                <a-select-option value="高中">高中</a-select-option>
                <!-- 根据需要添加更多选项 -->
              </a-select>
            </a-col>
          </a-row>
          <a-row :gutter="[30,30]">
            <a-col :span="12">
              <p class="text-left">时间段</p>

              <a-input-group compact style="display: flex;justify-content: start;" class="mt-2">
                <a-input style="width: 40%; text-align: center" placeholder="开始时间" v-model="education_experience.start_time"/>
                <a-input
                    style="width: 20%; border-left: 0; pointer-events: none; backgroundColor: #fff;"
                    placeholder="~" disabled
                />
                <a-input
                    style="width: 40%; text-align: center; border-left: 0;"
                    placeholder="毕业时间"
                    v-model="education_experience.end_time"
                />
              </a-input-group>
            </a-col>
            <a-col :span="12">
              <p class="text-left">专业</p>
              <a-input class="mt-2" placeholder="请选择专业" v-model="education_experience.profession"/>
            </a-col>
          </a-row>
          <a-row :gutter="[30,30]">
            <a-col :span="24">
              <p class="text-left">在校经历</p>
              <el-input type="textarea" :rows="5" v-model="education_experience.experience" class="mt-2"/>
            </a-col>
          </a-row>
        </div>
      </div>
    </section>
    <h1 class="text-left text-xl font-bold mt-7 mb-4" id="work">工作经历</h1>
    <section class="text-left space-y-4">
      <div class="p-4 border rounded-lg cursor-pointer" v-for="(item , index ) in  data2" :key="index" @click="item.isDown = !item.isDown" >
        <div class="flex justify-between">
          <h1 class="text-base font-bold">{{item.name}}</h1>
          <div>
            <i :class="`${!item.isDown  ? 'el-icon-arrow-down' : 'el-icon-arrow-up'} `"></i>
          </div>
        </div>
        <p class="mt-1">
          <span>{{item.zhiwei}}</span>
          <span class="px-4">|</span>
          <span>{{item.time}}</span>
        </p>
        <div :class="`${!item.isDown ? 'h-0' : 'h-full pt-5'}  overflow-hidden ` ">
          <a-row :gutter="[30,30]">
            <a-col :span="12">
              <p class="text-left">公司名称</p>
              <a-input class="mt-2" placeholder="请输入公司名称" v-model="work_experience.company"/>
            </a-col>
            <a-col :span="12">
              <p class="text-left">职位类型</p>
              <a-input class="mt-2" placeholder="例如：UI设计师" v-model="work_experience.position"/>
            </a-col>
          </a-row>
          <a-row :gutter="[30,30]">
            <a-col :span="12">
              <p class="text-left">在职时间</p>

              <a-input-group compact style="display: flex;justify-content: start;" class="mt-2">
                <a-input style="width: 40%; text-align: center" placeholder="选择年月" v-model="work_experience.start_time"/>
                <a-input
                    style="width: 20%; border-left: 0; pointer-events: none; backgroundColor: #fff;"
                    placeholder="~" disabled
                />
                <a-input
                    style="width: 40%; text-align: center; border-left: 0;"
                    placeholder="选择年月"
                    v-model="work_experience.end_time"
                />
              </a-input-group>
            </a-col>
          </a-row>
          <a-row :gutter="[30,30]">
            <a-col :span="24">
              <p class="text-left">工作经历</p>
              <el-input type="textarea" :rows="5" v-model="work_experience.experience" class="mt-2"/>
            </a-col>
          </a-row>
        </div>
      </div>
    </section>
    <h1 class="text-left text-xl font-bold mt-7 mb-4" id="project">项目经历</h1>
