                />
                <a-input
                    style="width: 40%; text-align: center; border-left: 0;"
                    placeholder="最高薪资"
                    v-model="project_experience.end_time"
                />
              </a-input-group>
            </a-col>
          </a-row>
          <a-row :gutter="[30,30]">
            <a-col :span="24">
              <p class="text-left">项目描述</p>
              <el-input type="textarea" :rows="5" v-model="project_experience.experience" class="mt-2"/>
            </a-col>
          </a-row>
        </div>
      </div>
